'use strict';
// Proposal v2: browser-local demonstrations. No server authentication or email delivery.
const legacy={render,renderAdmin,renderMobile,clientForm,clientDetail,employeeForm,employeeDetail,visitForm,visitDetail,settingsPage,reportsPage,timesheetDayDetail,renderMobileModal,collectNotes,action,validateVisit,exportReport};
const money=n=>nfmt(n,2)+' €';
function migrateV2(){
 if(db.proposalVersion===2)return;
 db.branches=[{id:'kaunas',name:'Kaunas'},{id:'siauliai',name:'Šiauliai'}];
 db.municipalities=[{id:'miestas',name:'Kauno miesto savivaldybė'},{id:'siauliai',name:'Šiaulių miesto savivaldybė'}];
 db.tasks=db.notes.map((n,i)=>({id:n.id,name:n.text,minutes:[30,40,45,30,25,20][i]||30,serviceId:db.services[i%db.services.length].id,active:n.active}));
 db.services.forEach(s=>Object.assign(s,{description:'Socialinė paslauga',unit:'val.',municipalities:['miestas','siauliai']}));
 db.rates=[];db.services.forEach((s,i)=>['miestas','siauliai'].forEach((m,j)=>{db.rates.push({id:uid(),serviceId:s.id,municipalityId:m,from:'2025-01-01',amount:18+i*4+j*2},{id:uid(),serviceId:s.id,municipalityId:m,from:'2026-01-01',amount:20+i*4+j*2})}));
 db.clients.forEach((c,i)=>Object.assign(c,{branchId:i<8?'kaunas':'siauliai',municipalityId:i<8?'miestas':'siauliai',assignments:c.services.map(serviceId=>({serviceId,supplement:3})),plan:db.tasks.filter(t=>t.serviceId===c.services[0]).slice(0,2).map(t=>t.id),suspensions:[],files:[],schedule:[]}));
 db.employees.forEach((em,i)=>Object.assign(em,{branchId:i%2?'siauliai':'kaunas',files:[]}));
 db.clients.slice(0,4).forEach((c,i)=>{c.schedule=[1,3,5].map(day=>({id:uid(),day,serviceId:c.services[0],employeeId:c.branchId==='kaunas'?'e1':'e2',start:String(8+i*2).padStart(2,'0')+':00',end:String(9+i*2).padStart(2,'0')+':30'}))});
 db.clients[2].suspensions=[{id:uid(),from:addDays(TODAY,-115),to:'',reason:'Laikinai paslaugomis nesinaudoja'}];
 db.settings={allowEmployeeOnly:true};db.internal=[];db.corrections=[];db.holidays=[TODAY.slice(0,4)+'-12-25',TODAY.slice(0,4)+'-12-26'];
 db.visits.forEach(v=>{v.rateSnapshot=rateAt(v.serviceId,client(v.clientId).municipalityId,v.date)?.amount??null;v.supplementSnapshot=3});
 db.emailEnabled=false;db.proposalVersion=2;
 notify('Atnaujintas darbo grafikas','Peržiūrėkite šios savaitės suplanuotus vizitus.',{branchId:'kaunas',employeeId:'e1',clientId:'c1',visitId:db.visits.find(v=>v.clientId==='c1')?.id},'vizitas');
 save();
}
function rateAt(serviceId,municipalityId,date=TODAY){return db.rates?.filter(r=>r.serviceId===serviceId&&r.municipalityId===municipalityId&&r.from<=date).sort((a,b)=>b.from.localeCompare(a.from))[0]}
function supplementAt(c,serviceId){return c.assignments?.find(a=>a.serviceId===serviceId)?.supplement||0}
function branchName(id){return db.branches.find(b=>b.id===id)?.name||'Nepriskirta'}
function muniName(id){return db.municipalities.find(b=>b.id===id)?.name||'Nepriskirta'}
function branchScope(){return ui.role.startsWith('coord:')?ui.role.slice(6):''}
function allowedClient(id){return !branchScope()||client(id).branchId===branchScope()}
function allowedEmployee(id){return !branchScope()||emp(id).branchId===branchScope()}
function allowedVisit(v){return v&&allowedClient(v.clientId)&&allowedEmployee(v.employeeId)}
function scopeData(fn){const full=db;if(!branchScope())return fn();db={...full,clients:full.clients.filter(c=>allowedClient(c.id)),employees:full.employees.filter(em=>allowedEmployee(em.id)),visits:full.visits.filter(allowedVisit),absences:full.absences.filter(a=>allowedEmployee(a.employeeId))};try{return fn()}finally{db=full}}
isAdmin=()=>ui.role==='admin'||ui.role.startsWith('coord:');
function persist(){try{localStorage.setItem(KEY,JSON.stringify(db));return true}catch(err){error('Nepavyko išsaugoti. Sumažinkite prisegtų failų kiekį.');return false}}
function notify(title,body,links={},kind='įvykis',key=''){if(!db.internal)return;if(key&&db.internal.some(n=>n.key===key))return;db.internal.push({id:uid(),title,body,...links,kind,key,at:new Date().toISOString(),readBy:[]})}
function notifyVisit(v,title='Pakeistas vizitas'){notify(title,`${client(v.clientId).name} · ${v.date} ${v.start}–${v.end}`,{clientId:v.clientId,employeeId:v.employeeId,visitId:v.id,branchId:client(v.clientId).branchId},'vizitas')}
function suspension(c,date=TODAY){return c.suspensions?.find(s=>s.from<=date&&(!s.to||s.to>=date))}
function suspensionDays(s,date=TODAY){let end=s.to&&s.to<date?s.to:date;return Math.max(0,Math.round((new Date(end+'T12:00')-new Date(s.from+'T12:00'))/86400000)+1)}
function checkOperationalAlerts(){const count=db.internal.length;for(const v of db.visits){if(v.status==='planned'&&new Date(v.date+'T'+v.start)<new Date())notify('Vizitas laiku nepradėtas',`${client(v.clientId).name} · ${v.date} ${v.start}`,{visitId:v.id,clientId:v.clientId,employeeId:v.employeeId,branchId:client(v.clientId).branchId},'vėlavimas','late:'+v.id)}for(const c of db.clients){let s=suspension(c);if(s&&suspensionDays(s)>=115)notify('Paslaugų sustabdymo riba',`${c.name}: paslaugos sustabdytos ${suspensionDays(s)} d. Stebima 120 dienų riba.`,{clientId:c.id,branchId:c.branchId},'sustabdymas','susp:'+s.id)}if(db.internal.length!==count)persist()}
function visibleNotifications(){return db.internal.filter(n=>isAdmin()?(!branchScope()||n.branchId===branchScope()):n.employeeId===ui.role).sort((a,b)=>b.at.localeCompare(a.at))}
function canNotice(n){return visibleNotifications().some(x=>x.id===n.id)}
function unreadCount(){return visibleNotifications().filter(n=>!n.readBy.includes(ui.role)).length}
function doneSave(message,view){if(!persist())return;closeModal();render();if(view)view();toast(message)}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">${empty()}</td></tr>`}</tbody></table></div>`}
function panel(title,body,action=''){return `<section class="panel"><div class="panel-head"><h2>${title}</h2>${action}</div><div class="panel-body">${body}</div></section>`}
function notice(text,cls='info'){return `<div class="notice ${cls}">${ic('alert')}<div>${text}</div></div>`}
function fselect(name,items,val,blank='Pasirinkite'){return select(name,items,val,blank)}
function form(title,id,body,action,wide=false){showModal(title,`<form id="${id}"><div class="form-error" role="alert"></div>${body}</form>`,btn('Atšaukti','close')+btn('Išsaugoti',action,'primary'),wide)}
function currentRate(c,s,date=TODAY){let r=rateAt(s,c.municipalityId,date);return r?money(r.amount)+'/val.':'Įkainis nenustatytas'}
migrateV2();
navItems.splice(6,1,['rates','briefcase','Paslaugos ir įkainiai'],['tasks','check','Darbų katalogas']);
navItems.find(n=>n[0]==='notifications')[2]='Vidiniai pranešimai';
render=function(){checkOperationalAlerts();const admin=isAdmin(),coord=branchScope(),name=ui.role==='admin'?'Administratorius':coord?'Koordinatorius':emp(ui.role).name;const nav=admin?navItems:[['mobile','calendar','Mano grafikas'],['myhistory','clock','Mano vizitai'],['notifications','mail','Pranešimai']];const title=nav.find(n=>n[0]===ui.page)?.[2]||'Darbo aplinka';
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="logo"><img src="./icon.svg" alt=""><span>paslaugos<span style="color:#c4d69f">.</span></span></div><div class="brand-sub">Socialinių paslaugų valdymas</div><p class="nav-label">DARBO APLINKA</p><nav class="nav" aria-label="Pagrindinis meniu">${nav.map(([id,icon,label])=>`<button data-action="nav" data-page="${id}" class="${ui.page===id?'active':''}">${ic(icon)}<span>${label}</span>${id==='notifications'&&unreadCount()?`<span class="count">${unreadCount()}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="side-user"><div class="avatar dark">${coord?'KO':admin?'AD':initials(name)}</div><div><b>${e(name)}</b><span>${coord?e(branchName(coord)):admin?'Visi padaliniai':'Darbuotojo aplinka'}</span></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">${ic('grid')}<span>${coord?e(branchName(coord)):'Darbo aplinka'}</span>${ic('chevron')}<strong>${title}</strong></div><div class="top-controls"><span class="demo-badge">DEMONSTRACIJA</span><label class="role-control"><span>Peržiūra:</span><select id="role" aria-label="Demonstracinė naudotojo rolė"><optgroup label="Administracija"><option value="admin" ${ui.role==='admin'?'selected':''}>Administratorius · visi padaliniai</option>${db.branches.map(b=>`<option value="coord:${b.id}" ${coord===b.id?'selected':''}>Koordinatorius · ${e(b.name)}</option>`).join('')}</optgroup><optgroup label="Darbuotojai">${options(db.employees.filter(x=>x.active),ui.role,null)}</optgroup></select></label></div></header><div class="content" id="content">${admin?scopeData(()=>renderAdmin()):ui.page==='notifications'?notificationsPage():renderMobile()}<footer class="footer"><span>© ${new Date().getFullYear()} Socialinių paslaugų valdymas</span><span>Demonstraciniai duomenys · Saugoma šioje naršyklėje</span></footer></div></main></div>`;
};
renderAdmin=function(){switch(ui.page){case'rates':return ratesPage();case'tasks':return tasksPage();case'notifications':return notificationsPage();default:return legacy.renderAdmin()}};
const baseCalendar=calendarPage;calendarPage=function(){let out=baseCalendar();return out.replace('<div class="page-head">','<div class="page-head">').replace(' Naujas vizitas</button>',` Naujas vizitas</button>${btn(ic('refresh')+' Formuoti mėnesį','generate','', 'style="margin-left:8px"')}`)};
// Expanded client and employee cards.
relativeInput=function(r={}){return `<div class="relative-row" data-relative="${r.id||uid()}"><input name="relativeName" aria-label="Artimojo vardas" placeholder="Artimojo vardas" value="${e(r.name||'')}" required maxlength="100"><input name="relativeEmail" aria-label="Artimojo el. paštas" placeholder="El. paštas" type="email" value="${e(r.email||'')}" required maxlength="120"><button type="button" class="icon-btn" data-action="remove-relative" title="Pašalinti kontaktą">${ic('close')}</button></div>`};
clientForm=function(id){const c=id?client(id):{name:'',phone:'',address:'',active:true,branchId:branchScope()||db.branches[0].id,municipalityId:'miestas',services:[],relatives:[],assignments:[]};modalState={type:'client',id};form(id?'Redaguoti klientą':'Naujas klientas','client-v2',`<div class="form-grid">${field('Vardas, pavardė *',input('name',c.name,'text','required maxlength="100"'))}${field('Telefonas *',input('phone',c.phone,'tel','required maxlength="30"'))}${field('Paslaugų teikimo adresas *',input('address',c.address,'text','required maxlength="200"'),true)}${field('Padalinys *',select('branchId',db.branches.filter(b=>!branchScope()||b.id===branchScope()),c.branchId))}${field('Savivaldybė *',select('municipalityId',db.municipalities,c.municipalityId))}${field('Būsena',`<select name="active"><option value="true" ${c.active?'selected':''}>Aktyvus</option><option value="false" ${!c.active?'selected':''}>Neaktyvus</option></select>`)}</div><div class="section-title">Paslaugos ir individualios priemokos</div><div class="assignments">${db.services.map(s=>`<div class="assignment-row" data-service="${s.id}"><label class="check-label"><input type="checkbox" name="services" value="${s.id}" ${c.services.includes(s.id)?'checked':''}>${e(s.name)}</label><span class="rate-label" data-rate="${s.id}">${currentRate(c,s.id)}</span><label>Priemoka, €/val.<input type="number" step="0.01" min="0" max="9999" name="supplement-${s.id}" value="${supplementAt(c,s.id)}" aria-label="${e(s.name)} priemoka"></label></div>`).join('')}</div><div class="section-title">Artimųjų kontaktai ${btn(ic('plus')+' Kontaktas','add-relative','small')}</div><div id="relatives">${c.relatives.map(relativeInput).join('')}</div><p class="hint">Kontaktinė informacija. Automatiniai laiškai artimiesiems šiame etape nenumatyti.</p>`,'v2-save-client',true)};
function planText(c){return (c.plan||[]).map(id=>db.tasks.find(t=>t.id===id)).filter(Boolean).map(t=>`<span class="tag">${e(t.name)} · ${t.minutes} min.</span>`).join(' ')||'<span class="hint">Planas dar nesudarytas</span>'}
clientDetail=function(id){if(!allowedClient(id))return;let c=client(id),vs=db.visits.filter(v=>v.clientId===id&&allowedVisit(v)).sort((a,b)=>visitSort(b,a)),sus=suspension(c);modalState={type:'client-detail',id};showModal(c.name,`<div class="detail-box"><div class="detail-grid"><div class="detail-item"><small>Kontaktai</small><b>${e(c.phone)}</b><p>${e(c.address)}</p></div><div class="detail-item"><small>Padalinys ir savivaldybė</small><b>${e(branchName(c.branchId))}</b><p>${e(muniName(c.municipalityId))}</p></div></div></div>${sus?notice(`<b>Paslaugos sustabdytos · ${suspensionDays(sus)} d.</b><br>${e(sus.reason)}. ${suspensionDays(sus)>=115?'Artėjama prie 120 dienų ribos arba ji pasiekta.':''}`,''):''}<div class="record-tabs"><button data-action="edit-client" data-id="${id}">Duomenys ir priemokos</button><button data-action="edit-plan" data-id="${id}">Pagalbos planas</button><button data-action="edit-schedule" data-id="${id}">Tipinis grafikas</button><button data-action="suspensions" data-id="${id}">Sustabdymai</button><button data-action="documents" data-kind="client" data-id="${id}">Dokumentai (${c.files.length})</button></div><div class="section-title">Paslaugos ir priemokos</div>${table(['Paslauga','Įkainis šiandien','Kliento priemoka'],c.services.map(s=>[e(service(s).name),currentRate(c,s),money(supplementAt(c,s))+'/val.']))}<div class="section-title">Individualus pagalbos planas</div><div class="detail-box pill-group">${planText(c)}</div><div class="section-title">Tipinis lankymo grafikas</div>${scheduleTable(c)}<div class="section-title">Artimųjų kontaktai</div>${table(['Vardas','El. paštas'],c.relatives.map(r=>[e(r.name),e(r.email)]))}<div class="section-title">Paslaugų istorija</div>${visitTable(vs.slice(0,15))}`,btn('Uždaryti','close'),true,'KLIENTO KORTELĖ')};
clientsPage=function(){let q=ui.search.toLocaleLowerCase('lt'),list=db.clients.filter(c=>(c.name+' '+c.address+' '+c.phone).toLocaleLowerCase('lt').includes(q)&&(!ui.service||c.services.includes(ui.service))&&(!ui.status||(ui.status==='suspended'?!!suspension(c):ui.status==='active'?c.active&&!suspension(c):!c.active)));return head('Klientai','Kortelės, pagalbos planai, tipiniai grafikai ir paslaugų sustabdymai.',btn(ic('plus')+' Naujas klientas','new-client','primary'))+panel('Klientų sąrašas <span class="tag grey">'+db.clients.length+'</span>',`<div class="toolbar">${searchBox('Ieškoti kliento, adreso…')}${selectFilter('service',db.services,'Visos paslaugos')}<select id="status" aria-label="Kliento būsena"><option value="">Visos būsenos</option>${[['active','Aktyvūs'],['suspended','Sustabdytos paslaugos'],['inactive','Neaktyvūs']].map(([id,name])=>`<option value="${id}" ${ui.status===id?'selected':''}>${name}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>Klientas</th><th>Kontaktai ir adresas</th><th>Padalinys</th><th>Paslaugos</th><th>Būsena</th><th></th></tr></thead><tbody>${list.map(c=>{let sus=suspension(c);return `<tr class="clickable" data-action="client-detail" data-id="${c.id}"><td><div class="person-cell"><span class="avatar">${initials(c.name)}</span><strong>${e(c.name)}</strong></div></td><td>${e(c.phone)}<span class="sub">${e(c.address)}</span></td><td>${e(branchName(c.branchId))}</td><td>${c.services.map(s=>`<span class="tag">${e(service(s).name)}</span>`).join(' ')}</td><td><span class="tag ${sus?'amber':c.active?'green':'grey'}">${sus?'Sustabdyta · '+suspensionDays(sus)+' d.':c.active?'Aktyvus':'Neaktyvus'}</span></td><td>${ic('chevron')}</td></tr>`}).join('')}</tbody></table></div>${list.length?'':empty()}<div class="table-foot">Rodoma ${list.length} iš ${db.clients.length} klientų</div>`)};
employeeForm=function(id){scopeData(()=>legacy.employeeForm(id));let em=id?emp(id):null;$('#employee-form .form-grid')?.insertAdjacentHTML('beforeend',field('Padalinys *',select('branchId',db.branches.filter(b=>!branchScope()||b.id===branchScope()),em?.branchId||branchScope()||'kaunas')))};
employeeDetail=function(id){if(!allowedEmployee(id))return;scopeData(()=>legacy.employeeDetail(id));$('.modal-body')?.insertAdjacentHTML('afterbegin',`<div class="record-tabs"><span class="tag">${e(branchName(emp(id).branchId))}</span>${btn('Dokumentai ('+emp(id).files.length+')','documents','small',`data-kind="employee" data-id="${id}"`)}</div>`)};
function planForm(id){let c=client(id);modalState={type:'plan',id};form('Individualus pagalbos planas · '+c.name,'plan-v2',`<p class="hint">Pasirinkti darbai darbuotojui bus rodomi kaip kliento plano privalomi darbai.</p><div class="simple-list">${db.tasks.filter(t=>t.active&&c.services.includes(t.serviceId)).map(t=>`<label class="item check-label"><input name="tasks" type="checkbox" value="${t.id}" ${c.plan.includes(t.id)?'checked':''}><span style="flex:1">${e(t.name)}</span><span class="tag">${t.minutes} min.</span></label>`).join('')}</div>`,'save-plan')}
const weekdays=['Sekmadienis','Pirmadienis','Antradienis','Trečiadienis','Ketvirtadienis','Penktadienis','Šeštadienis'];
function scheduleTable(c){return table(['Diena','Laikas','Paslauga','Darbuotojas'],c.schedule.map(t=>[weekdays[t.day],t.start+'–'+t.end,e(service(t.serviceId).name),e(emp(t.employeeId).name)]))}
function scheduleRow(c,t={}){return `<div class="schedule-row" data-template="${t.id||uid()}"><label>Diena<select name="day">${[1,2,3,4,5,6,0].map(d=>`<option value="${d}" ${t.day===d?'selected':''}>${weekdays[d]}</option>`).join('')}</select></label><label>Pradžia${input('start',t.start||'09:00','time','required')}</label><label>Pabaiga${input('end',t.end||'10:00','time','required')}</label><label>Paslauga${select('serviceId',db.services.filter(s=>c.services.includes(s.id)),t.serviceId)}</label><label>Darbuotojas${select('employeeId',db.employees.filter(em=>em.active&&em.branchId===c.branchId),t.employeeId)}</label>${ib('trash','remove-schedule','Pašalinti laiką')}</div>`}
function scheduleForm(id){let c=client(id);modalState={type:'schedule',id};form('Tipinis grafikas · '+c.name,'schedule-v2',`<p class="hint">Kiekvienam savaitės laikui priskirkite paslaugą ir darbuotoją. Iš šio šablono formuojamas mėnesio planas. Jau sukurti vizitai nekeičiami.</p><div id="schedule-rows">${c.schedule.map(t=>scheduleRow(c,t)).join('')}</div>${btn(ic('plus')+' Lankymo laikas','add-schedule','small')}<div class="notice info" style="margin-top:16px">${ic('calendar')}<div>Vienos dienos pakeitimus atlikite bendrame kalendoriuje, redaguodami konkretų vizitą.</div></div>`,'save-schedule',true)}
function suspensionForm(id){let c=client(id);modalState={type:'suspensions',id};showModal('Paslaugų sustabdymai · '+c.name,`<form id="suspension-v2"><div class="form-error" role="alert"></div><div class="form-grid">${field('Nuo *',input('from',TODAY,'date','required'))}${field('Iki (nebūtina)',input('to','','date'))}${field('Priežastis *',input('reason','','text','required maxlength="500"'),true)}</div></form><div class="section-title">Sustabdymų istorija</div>${table(['Laikotarpis','Priežastis','Trukmė',''],c.suspensions.map(s=>[e(s.from)+' – '+e(s.to||'iki atnaujinimo'),e(s.reason),suspensionDays(s)+' d.',!s.to||s.to>=TODAY?btn('Atnaujinti paslaugas','resume-service','small',`data-id="${s.id}"`):'Baigta']))}<p class="hint">Sustabdymo laikotarpiu nauji vizitai negeneruojami. Jau suplanuotus vizitus koordinatorius peržiūri kalendoriuje. Rodoma praėjusi sustabdymo trukmė, stebima 120 dienų riba.</p>`,btn('Uždaryti','close')+btn('Registruoti sustabdymą','save-suspension','primary'),true)}
function documentOwner(kind,id){return kind==='client'?client(id):emp(id)}
function documentForm(kind,id){let owner=documentOwner(kind,id);modalState={type:'documents',kind,id};showModal('Dokumentai · '+owner.name,`<div class="form-error" role="alert"></div><label class="file-upload">Pridėti dokumentą<input id="document-file" type="file" accept=".pdf,.doc,.docx,.xlsx,.xls,.png,.jpg,.jpeg,.txt"></label><p class="hint">Demonstracijoje iki 2 MB vienam failui; dokumentai saugomi tik šioje naršyklėje.</p><div class="section-title">Prisegti failai</div>${table(['Failas','Dydis','Pridėta',''],owner.files.map(f=>[e(f.name),nfmt(Math.max(0.1,f.size/1024))+' KB',e(f.date),btn('Atidaryti / atsisiųsti','download-document','small',`data-id="${f.id}"`)]))}`,btn('Uždaryti','close'))}
// Catalogue, effective-dated prices, and tasks.
function ratesPage(){let q=(ui.search||'').toLowerCase();return head('Paslaugos ir įkainiai','Katalogas, savivaldybių įkainiai ir jų galiojimo istorija.',btn(ic('plus')+' Nauja paslauga','new-service-v2','primary'))+panel('Paslaugų katalogas',`${searchBox('Ieškoti paslaugos…')}${table(['Paslauga','Matavimo vienetas','Savivaldybės',''],db.services.filter(s=>s.name.toLowerCase().includes(q)).map(s=>[e(s.name)+`<span class="sub">${e(s.description)}</span>`,e(s.unit),s.municipalities.map(m=>e(muniName(m))).join('<br>'),btn('Įkainiai ir istorija','rate-history','small',`data-id="${s.id}"`)+btn('Redaguoti','edit-service-v2','small',`data-id="${s.id}"`)+ib('trash','delete-service','Pašalinti paslaugą',`data-id="${s.id}"`)]))}`)}
function serviceV2Form(id){let s=id?service(id):{name:'',description:'',unit:'val.',municipalities:[]};modalState={type:'service-v2',id};form(id?'Redaguoti paslaugą':'Nauja paslauga','service-v2',`<div class="form-grid">${field('Pavadinimas *',input('name',s.name,'text','required maxlength="160"'),true)}${field('Aprašymas',`<textarea name="description" maxlength="1000">${e(s.description)}</textarea>`,true)}${field('Matavimo vienetas *',input('unit',s.unit,'text','required maxlength="20"'))}</div><div class="section-title">Savivaldybės *</div>${db.municipalities.map(m=>`<label class="check-label"><input name="municipalities" type="checkbox" value="${m.id}" ${s.municipalities.includes(m.id)?'checked':''}>${e(m.name)}</label>`).join('')}`,'save-service-v2')}
function rateHistory(id){let s=service(id);modalState={type:'rate-history',id};showModal('Įkainiai · '+s.name,`${notice('Naujas įkainis taikomas nuo pasirinktos datos. Užregistruotuose istoriniuose vizituose išlieka išsaugotas įkainis.')}<form id="rate-v2" style="margin-top:16px"><div class="form-error" role="alert"></div><div class="form-grid">${field('Savivaldybė *',select('municipalityId',db.municipalities.filter(m=>s.municipalities.includes(m.id))))}${field('Galioja nuo *',input('from',TODAY,'date','required'))}${field('Įkainis, €/val. *',input('amount','','number','required min="0.01" max="9999" step="0.01"'))}</div></form><div class="section-title">Įkainių istorija</div>${table(['Savivaldybė','Galioja nuo','Galioja iki','Įkainis'],db.rates.filter(r=>r.serviceId===id).sort((a,b)=>b.from.localeCompare(a.from)).map(r=>{let next=db.rates.filter(n=>n.serviceId===id&&n.municipalityId===r.municipalityId&&n.from>r.from).sort((a,b)=>a.from.localeCompare(b.from))[0];return [e(muniName(r.municipalityId)),r.from,next?addDays(next.from,-1):'–',money(r.amount)]}))}`,btn('Uždaryti','close')+btn('Pridėti naują įkainį','save-rate','primary'),true)}
function tasksPage(){return head('Darbų katalogas','Darbai ir norminės trukmės individualiems klientų planams.',btn(ic('plus')+' Naujas darbas','new-task','primary'))+panel('Darbai',table(['Darbas','Paslauga','Norminė trukmė','Būsena',''],db.tasks.map(t=>[e(t.name),e(service(t.serviceId).name),t.minutes+' min.',t.active?'Aktyvus':'Išjungtas',btn('Redaguoti','edit-task','small',`data-id="${t.id}"`)])))}
function taskForm(id){let t=id?db.tasks.find(t=>t.id===id):{name:'',serviceId:db.services[0]?.id,minutes:30,active:true};modalState={type:'task',id};form(id?'Redaguoti darbą':'Naujas darbas','task-v2',`<div class="form-grid">${field('Darbo pavadinimas *',input('name',t.name,'text','required maxlength="160"'),true)}${field('Paslauga *',select('serviceId',db.services,t.serviceId))}${field('Norminė trukmė, min. *',input('minutes',t.minutes,'number','required min="1" max="1440"'))}${field('Būsena',`<select name="active"><option value="true" ${t.active?'selected':''}>Aktyvus</option><option value="false" ${!t.active?'selected':''}>Išjungtas</option></select>`)}</div>`,'save-task')}
function generatePreview(month){let pending=[],skipped=[];for(let c of db.clients.filter(c=>c.active&&allowedClient(c.id))){for(let date of rangeDays(month+'-01',monthRange(month).to)){if(suspension(c,date))continue;let day=new Date(date+'T12:00').getDay();for(let t of c.schedule.filter(t=>t.day===day)){let key=[c.id,t.id,date].join(':');if(db.visits.some(v=>v.templateKey===key||(v.clientId===c.id&&v.date===date&&v.start===t.start&&v.serviceId===t.serviceId)))continue;let v={id:uid(),clientId:c.id,employeeId:t.employeeId,serviceId:t.serviceId,date,start:t.start,end:t.end,templateKey:key,status:'planned',notes:[],comment:'',actualStart:null,actualEnd:null,signatures:null,replacement:null,rateSnapshot:rateAt(t.serviceId,c.municipalityId,date)?.amount??null,supplementSnapshot:supplementAt(c,t.serviceId)};let err=validateVisit(v,null,pending);if(err)skipped.push({...v,error:err});else pending.push(v)}}}return {pending,skipped}}
function generatorForm(){modalState={type:'generator',preview:null};showModal('Formuoti mėnesio vizitus',`<form id="generate-v2"><div class="form-error" role="alert"></div>${field('Mėnuo *',input('generateMonth',iso(new Date(Number(MONTH.slice(0,4)),Number(MONTH.slice(5)),1)).slice(0,7),'month','required'))}<p class="hint">Vizitai kuriami pagal klientų tipinius grafikus ir juose priskirtus darbuotojus. Sustabdyti laikotarpiai praleidžiami, jau sukurti vizitai nekartojami.</p></form><div id="generation-result"></div>`,btn('Uždaryti','close')+btn('Peržiūrėti planą','preview-generation','primary'),true)}
// Internal messages and incidents.
notificationsPage=function(){let all=visibleNotifications(),list=all.filter(n=>!ui.onlyUnread||!n.readBy.includes(ui.role));return head('Vidiniai pranešimai','Vizitų pakeitimai, neatvykimai, pavadavimai ir operaciniai įvykiai.',btn('Pažymėti visus perskaitytais','read-all'))+panel('Pranešimų sąrašas',`<label class="check-label" style="margin-bottom:15px"><input type="checkbox" id="onlyUnread" ${ui.onlyUnread?'checked':''}>Tik neperskaityti (${unreadCount()})</label>${table(['Data','Įvykis','Informacija','Būsena',''],list.map(n=>[e(n.at.slice(0,10))+'<span class="sub">'+timeFmt(n.at)+'</span>',e(n.title),e(n.body),`<span class="tag ${n.readBy.includes(ui.role)?'grey':'blue'}">${n.readBy.includes(ui.role)?'Perskaityta':'Nauja'}</span>`,btn('Peržiūrėti','notice-detail','small',`data-id="${n.id}"`)]))}`)+`<p class="hint">Pranešimai formuojami šios demonstracijos veiksmų metu. Vėlavimai tikrinami atidarant ar atnaujinant ekraną.</p>`};
// Mobile work plan and exceptional signatures.

renderMobile=function(){return legacy.renderMobile().replace('Baigdami pasirinksite atliktus darbus, o darbuotojas ir klientas pasirašys ekrane.','Baigdami pažymėsite kliento plano darbus ir patvirtinsite vizitą parašais. Jei leidžiama, užregistruosite kliento nepasirašymo priežastį.')};

renderMobileModal=function(){legacy.renderMobileModal();let ms=modalState,v=db.visits.find(v=>v.id===ms.id),c=client(v.clientId);if(ms.step==='notes'){let tasks=db.tasks.filter(t=>t.active&&c.services.includes(t.serviceId)),mandatory=tasks.filter(t=>c.plan.includes(t.id)),other=tasks.filter(t=>!c.plan.includes(t.id));let grid=$('.note-grid');if(grid)grid.outerHTML=`<div class="required-work"><h3>Kliento plano privalomi darbai</h3><div class="note-grid">${mandatory.map(t=>mobileTask(t,ms,true)).join('')||'<p class="hint">Privalomi darbai nepažymėti.</p>'}</div><h3 style="margin-top:16px">Papildomi darbai</h3><div class="note-grid">${other.map(t=>mobileTask(t,ms,false)).join('')||'<p class="hint">Papildomų darbų nėra.</p>'}</div></div>`;$('.modal-body textarea')?.nextElementSibling?.remove();let info=$('.modal-body .field small');if(info)info.textContent='Užrašai išsaugomi vizito istorijoje.'}
 if(ms.step==='sign'){let signatureLabel=$('.modal-body .section-title');if(signatureLabel)signatureLabel.textContent='Vizito patvirtinimas';if(db.settings.allowEmployeeOnly){$('.signature-grid')?.insertAdjacentHTML('afterend',`<div class="signature-exception"><label class="check-label"><input id="clientCannotSign" type="checkbox" ${ms.clientCannotSign?'checked':''}>Klientas negali pasirašyti</label><div id="no-sign-reason" ${ms.clientCannotSign?'':'hidden'}>${field('Nepasirašymo priežastis *',`<textarea name="noSignReason" maxlength="1000">${e(ms.noSignReason||'')}</textarea>`,true)}</div></div>`)} }
 if(ms.step==='sign'){for(let p of $$('.modal-body p.hint'))if(p.textContent.includes('Pasirašykite pirštu'))p.textContent='Darbuotojo parašas būtinas. Kliento parašą gali pakeisti nepasirašymo priežastis, kai ši išimtis įjungta nustatymuose.'}
 if(ms.step==='done'){let box=$('.modal-body .notice');if(box)box.innerHTML=ic('check')+`<div><b>Vizitas išsaugotas</b>Atlikti darbai, darbo laikas, GPS ir parašai saugomi vizito istorijoje.${v.noSignReason?' Kliento nepasirašymo priežastis užregistruota.':''}</div>`}
};
function mobileTask(t,ms,required){return `<label class="note-choice"><input type="checkbox" name="mobile-note" value="${e(t.name)}" ${ms.noteValues.includes(t.name)?'checked':''}><span>${e(t.name)}<small style="display:block">${t.minutes} min.${required?' · plano darbas':''}</small></span></label>`}
visitDetail=function(id){let v=db.visits.find(v=>v.id===id);if(!v||!allowedVisit(v))return;legacy.visitDetail(id);let body=$('.modal-body');if(!body)return;const oldNotice=body.querySelector('.notice.success');if(oldNotice)oldNotice.remove();body.insertAdjacentHTML('beforeend',`${isAdmin()?`<div class="section-title">Paslaugos įkainis vizito metu</div><div class="detail-box">${v.rateSnapshot==null?'Įkainis neužregistruotas':money(v.rateSnapshot)+'/val.'} · Kliento priemoka ${money(v.supplementSnapshot||0)}/val.</div>`:''}${v.noSignReason?notice('<b>Klientas nepasirašė</b><br>'+e(v.noSignReason)):''}`);if(isAdmin()&&v.status==='done')$('.modal-actions')?.insertAdjacentHTML('afterbegin',btn('Koreguoti laiką','correct-time','',`data-id="${id}"`))};
validateVisit=function(d,exclude=null,batch=[]){if(!allowedClient(d.clientId)||!allowedEmployee(d.employeeId))return 'Pasirinkto kliento arba darbuotojo padalinys neprieinamas.';if(emp(d.employeeId).branchId!==client(d.clientId).branchId)return 'Darbuotojas ir klientas turi priklausyti tam pačiam padaliniui.';if(suspension(client(d.clientId),d.date))return 'Kliento paslaugos šiuo laikotarpiu sustabdytos.';return legacy.validateVisit(d,exclude,batch)};
visitForm=function(id,prefill={}){scopeData(()=>legacy.visitForm(id,prefill))};
// Working-time categories use a configurable demonstration calendar, no pay calculation.
function categoryHours(v){let result={ordinary:0,night:0,weekend:0,holiday:0};if(v.status!=='done'||!v.actualStart||!v.actualEnd)return result;let a=new Date(v.actualStart),b=new Date(v.actualEnd);if(!(b>a))return result;for(let t=+a;t<+b;){let d=new Date(t),next=Math.min(+b,t+60000-(d.getSeconds()*1000+d.getMilliseconds())),h=(next-t)/3600000,hour=d.getHours();result[hour>=22||hour<6?'night':'ordinary']+=h;if([0,6].includes(d.getDay()))result.weekend+=h;if(db.holidays.includes(iso(d)))result.holiday+=h;t=next}return result}
function categorizedRows(){return reportWorkers(reportVisits()).map(em=>{let totals={ordinary:0,night:0,weekend:0,holiday:0};for(let v of reportVisits().filter(v=>v.employeeId===em.id)){let x=categoryHours(v);for(let k of Object.keys(totals))totals[k]+=x[k]}return {em,...totals}})}
reportsPage=function(){if(ui.reportTab==='categories')return head('Darbo laiko klasifikavimas','Darbo valandų rūšys ir koregavimo istorija.',btn('Eksportuoti CSV','export-report'))+panel('Valandų rūšys',`<div class="record-tabs">${btn('Mėnesio tabelis','report-tab','', 'data-tab="timesheet"')}${btn('Valandų rūšys','report-tab','active','data-tab="categories"')}${btn('Koregavimų istorija','report-tab','','data-tab="corrections"')}</div><div class="toolbar">${commonFilters(true)}</div>${table(['Darbuotojas','Faktas','Įprastos','Naktinės','Iš jų savaitgalio','Iš jų šventinės'],categorizedRows().map(r=>[e(r.em.name),nfmt(r.ordinary+r.night,2),nfmt(r.ordinary,2),nfmt(r.night,2),nfmt(r.weekend,2),nfmt(r.holiday,2)]))}<p class="hint">Valandos. Įprastos ir naktinės (22–6 val.) sudaro visą faktą. Savaitgalio ir šventinės valandos yra papildomi pjūviai, todėl jų nepridėkite prie fakto. Šventinių dienų datos taikomos pagal bendrą kalendorių.</p>`);
 if(ui.reportTab==='corrections')return head('Darbo laiko koregavimų istorija','Išsaugomos ankstesnės ir naujos reikšmės, priežastis ir koregavęs naudotojas.')+panel('Koregavimai',`<div class="record-tabs">${btn('Mėnesio tabelis','report-tab','','data-tab="timesheet"')}${btn('Valandų rūšys','report-tab','','data-tab="categories"')}</div>${table(['Kada / kas','Darbuotojas','Prieš','Po','Priežastis',''],db.corrections.filter(c=>allowedVisit(db.visits.find(v=>v.id===c.visitId))).map(c=>[e(c.at.slice(0,10))+'<span class="sub">'+e(c.by)+'</span>',e(emp(c.employeeId).name),e(localInput(c.before.start).replace('T',' '))+' – '+e(localInput(c.before.end).replace('T',' ')),e(localInput(c.after.start).replace('T',' '))+' – '+e(localInput(c.after.end).replace('T',' ')),e(c.reason),btn('Vizitas','visit-detail','small',`data-id="${c.visitId}"`)]))}`);
 let html=legacy.reportsPage();return html.replace('</div></div>\n',`${btn('Valandų rūšys','report-tab','','data-tab="categories"')}${btn('Koregavimų istorija','report-tab','','data-tab="corrections"')}</div></div>\n`)};
timesheetDayDetail=function(id,date){legacy.timesheetDayDetail(id,date);if(isAdmin()){let list=reportVisits().filter(v=>v.employeeId===id&&v.date===date&&v.status==='done');$('.modal-body')?.insertAdjacentHTML('beforeend',`<div class="record-tabs">${list.map(v=>btn('Koreguoti '+v.start+'–'+v.end,'correct-time','small',`data-id="${v.id}"`)).join('')}</div>`)}};
function localInput(isoString){let d=new Date(isoString);return iso(d)+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')}
function correctionForm(id){let v=db.visits.find(v=>v.id===id);modalState={type:'correction',id};form('Koreguoti faktinį vizito laiką','correction-v2',`<p class="subtitle">${e(client(v.clientId).name)} · ${e(emp(v.employeeId).name)}</p><div class="form-grid">${field('Faktinė pradžia *',input('start',localInput(v.actualStart),'datetime-local','required'))}${field('Faktinė pabaiga *',input('end',localInput(v.actualEnd),'datetime-local','required'))}${field('Koregavimo priežastis *',`<textarea name="reason" required maxlength="1000"></textarea>`,true)}</div><p class="hint">Pakeitimas atnaujins faktinį laiką tabelyje. Ankstesni laikai ir priežastis liks koregavimų istorijoje.</p>`,'save-correction')}
exportReport=function(){if(ui.reportTab==='categories'){downloadCSV('Valandu_rusys',['Darbuotojas','Faktas','Įprastos','Naktinės','Iš jų savaitgalio','Iš jų šventinės'],categorizedRows().map(r=>[r.em.name,...[r.ordinary+r.night,r.ordinary,r.night,r.weekend,r.holiday].map(n=>nfmt(n,3))]));return}return scopeData(()=>legacy.exportReport())};
// Settings live next to the work catalogue, keeping administration out of worker flows.
const oldTasksPage=tasksPage;tasksPage=function(){return oldTasksPage()+panel('Vizito patvirtinimas',`<label class="check-label"><input type="checkbox" id="allowEmployeeOnly" ${db.settings.allowEmployeeOnly?'checked':''}>Leisti užbaigti vizitą tik su darbuotojo parašu, nurodžius kliento nepasirašymo priežastį</label>`)};
// Actions and validation shared by desktop and the standalone HTML export.

action=async function(a,b={dataset:{}}){let id=b.dataset.id,ms=modalState;if(['new-incident','save-incident','import-template','apply-import','add-holiday','remove-holiday'].includes(a))return;if(a==='nav'&&['incidents','import'].includes(b.dataset.page))return;if(a==='visit-detail'&&!isAdmin()&&db.visits.find(v=>v.id===id)?.employeeId!==ui.role)return;const workerActions=['nav','notice-detail','read-all','finish-visit'];if(!isAdmin()&&!workerActions.includes(a))return legacy.action(a,b);
 if(isAdmin()){
  const clientActions=['edit-client','client-detail','edit-plan','edit-schedule','suspensions'];if(clientActions.includes(a)&&!allowedClient(id))return toast('Šio padalinio duomenys neprieinami.');
  if(['employee-detail','edit-employee','view-as-employee'].includes(a)&&!allowedEmployee(id))return toast('Šio padalinio duomenys neprieinami.');
  if(['visit-detail','edit-visit','delete-visit','correct-time'].includes(a)&&!allowedVisit(db.visits.find(v=>v.id===id)))return toast('Šio padalinio vizitas neprieinamas.');
 }
 switch(a){
 case'nav':if(isAdmin()||['mobile','myhistory','notifications'].includes(b.dataset.page)){ui.page=b.dataset.page;resetFilters();render()}return;
 case'v2-save-client':{if(!$('#client-v2').reportValidity())return;let d=formData('client-v2'),services=$$('input[name="services"]:checked').map(x=>x.value);if(!services.length)return error('Pasirinkite bent vieną paslaugą.');if(branchScope()&&d.branchId!==branchScope())return error('Padalinys neprieinamas.');let assignments=[];for(let s of services){let svc=service(s);if(!svc.municipalities.includes(d.municipalityId))return error('Paslauga „'+svc.name+'“ neteikiama pasirinktai savivaldybei.');let r=rateAt(s,d.municipalityId),supplement=Number(d['supplement-'+s]);if(!r)return error('Pirmiausia nustatykite galiojantį paslaugos įkainį šiai savivaldybei.');if(!Number.isFinite(supplement)||supplement<0||supplement>r.amount)return error('Priemoka turi būti nuo 0 iki paslaugos kainos ('+money(r.amount)+').');let employeeIds=$$('input[name="assigned-'+s+'"]:checked').map(x=>x.value);if(employeeIds.some(id=>!db.employees.some(em=>em.id===id&&em.active&&em.branchId===d.branchId)))return error('Priskirkite aktyvius to paties padalinio darbuotojus.');assignments.push({serviceId:s,supplement,employeeIds})}let old=ms.id?client(ms.id):null;if(old&&old.branchId!==d.branchId&&db.visits.some(v=>v.clientId===old.id))return error('Kliento, turinčio vizitų, padalinio keisti šiame demo negalima.');let relatives=$$('.relative-row').map(row=>({id:row.dataset.relative,name:$('[name="relativeName"]',row).value.trim(),email:$('[name="relativeEmail"]',row).value.trim(),notify:false})),obj={...(old||{id:uid(),plan:[],schedule:[],suspensions:[],files:[]}),name:d.name.trim(),phone:d.phone.trim(),address:d.address.trim(),active:d.active==='true',branchId:d.branchId,municipalityId:d.municipalityId,services,assignments,relatives};if(!obj.name||!obj.address||!obj.phone)return error('Užpildykite vardą, adresą ir telefoną.');obj.plan=obj.plan.filter(t=>services.includes(db.tasks.find(x=>x.id===t)?.serviceId));obj.schedule=obj.schedule.filter(t=>services.includes(t.serviceId));let at=db.clients.findIndex(c=>c.id===obj.id);if(at<0)db.clients.push(obj);else db.clients[at]=obj;doneSave('Kliento kortelė išsaugota',()=>clientDetail(obj.id));return}
 case'save-employee':{if(!$('#employee-form').reportValidity())return;let d=formData('employee-form');if(!d.name.trim()||branchScope()&&d.branchId!==branchScope())return error('Patikrinkite vardą ir padalinį.');if(db.employees.some(e=>e.id!==ms.id&&e.email.toLowerCase()===d.email.toLowerCase()))return error('Toks el. paštas jau naudojamas.');let old=ms.id?emp(ms.id):null;if(old&&old.branchId!==d.branchId&&db.visits.some(v=>v.employeeId===old.id))return error('Darbuotojo, turinčio vizitų, padalinio keisti šiame demo negalima.');let obj={...(old||{id:uid(),files:[]}),name:d.name.trim(),phone:d.phone.trim(),email:d.email.trim(),capacity:Number(d.capacity),active:d.active==='true',branchId:d.branchId},at=db.employees.findIndex(x=>x.id===obj.id);if(at<0)db.employees.push(obj);else db.employees[at]=obj;doneSave('Darbuotojas išsaugotas');return}
 case'edit-plan':planForm(id);return;
 case'save-plan':{let c=client(ms.id);c.plan=$$('input[name="tasks"]:checked').map(x=>x.value);doneSave('Pagalbos planas išsaugotas',()=>clientDetail(c.id));return}
 case'edit-schedule':scheduleForm(id);return;
 case'add-schedule':$('#schedule-rows').insertAdjacentHTML('beforeend',scheduleRow(client(ms.id)));return;
 case'remove-schedule':b.closest('.schedule-row').remove();return;
 case'save-schedule':{if(!$('#schedule-v2').reportValidity())return;let c=client(ms.id),rows=$$('.schedule-row').map(row=>{let get=n=>$('[name="'+n+'"]',row).value;return {id:row.dataset.template,day:Number(get('day')),start:get('start'),end:get('end'),serviceId:get('serviceId'),employeeId:get('employeeId')}});for(let t of rows){if(t.end<=t.start)return error('Pabaiga turi būti vėliau nei pradžia.');if(!c.services.includes(t.serviceId)||emp(t.employeeId).branchId!==c.branchId)return error('Patikrinkite paslaugą ir darbuotojo padalinį.')}if(rows.some((t,i)=>rows.some((o,j)=>j<i&&o.day===t.day&&o.start<t.end&&o.end>t.start)))return error('Kliento tipinio grafiko laikai persidengia.');c.schedule=rows;doneSave('Tipinis grafikas išsaugotas',()=>clientDetail(c.id));return}
 case'suspensions':suspensionForm(id);return;
 case'save-suspension':{if(!$('#suspension-v2').reportValidity())return;let c=client(ms.id),d=formData('suspension-v2');if(!d.reason.trim())return error('Nurodykite priežastį.');if(d.to&&d.to<d.from)return error('Pabaiga negali būti anksčiau nei pradžia.');if(c.suspensions.some(s=>s.from<=(d.to||'9999-12-31')&&(!s.to||s.to>=d.from)))return error('Sustabdymų laikotarpiai persidengia.');c.suspensions.push({id:uid(),...d,reason:d.reason.trim()});notify('Sustabdytos kliento paslaugos',c.name+' · '+d.reason,{clientId:c.id,branchId:c.branchId},'sustabdymas');doneSave('Sustabdymas užregistruotas',()=>clientDetail(c.id));return}
 case'resume-service':{let c=client(ms.id),s=c.suspensions.find(s=>s.id===id);if(s.from>TODAY){c.suspensions=c.suspensions.filter(s=>s.id!==id)}else{s.to=addDays(TODAY,-1);if(s.to<s.from)c.suspensions=c.suspensions.filter(x=>x.id!==id)}notify('Atnaujintos kliento paslaugos',c.name,{clientId:c.id,branchId:c.branchId},'sustabdymas');doneSave('Paslaugos atnaujintos',()=>clientDetail(c.id));return}
 case'documents':if(b.dataset.kind==='client'?!allowedClient(id):!allowedEmployee(id))return;documentForm(b.dataset.kind,id);return;
 case'download-document':{let f=documentOwner(ms.kind,ms.id).files.find(f=>f.id===id);if(f){let a=document.createElement('a');a.href=f.data;a.download=f.name;a.click()}return}
 case'new-service-v2':serviceV2Form();return;case'edit-service-v2':serviceV2Form(id);return;
 case'save-service-v2':{if(!$('#service-v2').reportValidity())return;let d=formData('service-v2'),municipalities=$$('input[name="municipalities"]:checked').map(x=>x.value);if(!d.name.trim()||!municipalities.length)return error('Nurodykite pavadinimą ir bent vieną savivaldybę.');if(db.services.some(s=>s.id!==ms.id&&s.name.toLowerCase()===d.name.trim().toLowerCase()))return error('Tokia paslauga jau yra.');let old=ms.id?service(ms.id):null;if(old&&db.clients.some(c=>c.services.includes(old.id)&&!municipalities.includes(c.municipalityId)))return error('Savivaldybė naudojama klientų priskyrimuose ir negali būti pašalinta.');let obj={id:ms.id||uid(),name:d.name.trim(),description:d.description.trim(),unit:d.unit.trim(),municipalities};if(old)Object.assign(old,obj);else db.services.push(obj);doneSave('Paslauga išsaugota');return}
 case'rate-history':rateHistory(id);return;
 case'save-rate':{if(!$('#rate-v2').reportValidity())return;let d=formData('rate-v2'),amount=Number(d.amount);if(db.rates.some(r=>r.serviceId===ms.id&&r.municipalityId===d.municipalityId&&r.from===d.from))return error('Šiai datai įkainis jau yra. Naujam įkainiui pasirinkite kitą galiojimo pradžią.');if(!(amount>0))return error('Įkainis turi būti teigiamas.');if(db.clients.some(c=>c.municipalityId===d.municipalityId&&supplementAt(c,ms.id)>amount))return error('Naujas įkainis mažesnis už nustatytą kliento priemoką. Pirmiausia suderinkite priemoką.');let sid=ms.id;db.rates.push({id:uid(),serviceId:sid,municipalityId:d.municipalityId,from:d.from,amount});doneSave('Naujas įkainis išsaugotas',()=>rateHistory(sid));return}
 case'new-task':taskForm();return;case'edit-task':taskForm(id);return;
 case'save-task':{if(!$('#task-v2').reportValidity())return;let d=formData('task-v2');if(!d.name.trim())return error('Įveskite darbo pavadinimą.');let old=db.tasks.find(t=>t.id===ms.id);if(old&&old.serviceId!==d.serviceId&&db.clients.some(c=>c.plan.includes(old.id)))return error('Darbas naudojamas pagalbos plane. Pirmiausia atnaujinkite planą.');let obj={id:ms.id||uid(),name:d.name.trim(),minutes:Number(d.minutes),serviceId:d.serviceId,active:d.active==='true'};if(old)Object.assign(old,obj);else db.tasks.push(obj);doneSave('Darbas išsaugotas');return}
 case'generate':generatorForm();return;
 case'preview-generation':{if(!$('#generate-v2').reportValidity())return;let month=$('[name="generateMonth"]').value;if(!/^\d{4}-\d{2}$/.test(month))return error('Pasirinkite mėnesį.');ms.month=month;ms.preview=generatePreview(month);let p=ms.preview;$('#generation-result').innerHTML=`<div class="section-title">Plano peržiūra</div>${notice(`<b>Galima sukurti ${p.pending.length} vizitų.</b> ${p.skipped.length} vizitų turi konfliktų ir nebus sukurti. Esami vizitai nekartojami.`)}${p.pending.length?table(['Data','Laikas','Klientas','Darbuotojas'],p.pending.slice(0,30).map(v=>[v.date,v.start+'–'+v.end,e(client(v.clientId).name),e(emp(v.employeeId).name)])):''}${p.pending.length>30?'<p class="hint">Rodomi pirmi 30 vizitų.</p>':''}${p.skipped.length?`<div class="section-title">Konfliktai</div>${table(['Data','Klientas','Priežastis'],p.skipped.slice(0,20).map(v=>[v.date,e(client(v.clientId).name),e(v.error)]))}`:''}`;$('.modal-actions').innerHTML=btn('Uždaryti','close')+btn('Perskaičiuoti','preview-generation')+(p.pending.length?btn('Sukurti '+p.pending.length+' vizitų','apply-generation','primary'):'');return}
 case'apply-generation':{if(!ms.preview)return;let fresh=generatePreview(ms.month);if(fresh.pending.length!==ms.preview.pending.length)return error('Duomenys pasikeitė. Dar kartą peržiūrėkite planą.');for(let v of fresh.pending){db.visits.push(v);notifyVisit(v,'Priskirtas naujas vizitas')}let n=fresh.pending.length;doneSave(n+' vizitų sukurta');return}
 case'notice-detail':{let n=db.internal.find(n=>n.id===id);if(!n||!canNotice(n))return;if(!n.readBy.includes(ui.role))n.readBy.push(ui.role);persist();render();showModal(n.title,`<p class="subtitle">${e(n.at.slice(0,10))} ${timeFmt(n.at)}</p><p style="line-height:1.8;white-space:pre-wrap">${e(n.body)}</p>`,btn('Uždaryti','close')+(n.visitId?btn('Atidaryti vizitą','visit-detail','primary',`data-id="${n.visitId}"`):isAdmin()&&n.clientId?btn('Kliento kortelė','client-detail','primary',`data-id="${n.clientId}"`):''));return}
 case'read-all':for(let n of visibleNotifications())if(!n.readBy.includes(ui.role))n.readBy.push(ui.role);persist();render();return;
 case'finish-visit':{if(ms?.type!=='mobile'||ms.step!=='sign')return;captureSignatures();let v=db.visits.find(v=>v.id===ms.id);if(v.employeeId!==ui.role||v.status!=='active')return;if(!ms.signatures.employee)return error('Būtinas darbuotojo parašas.');let cannot=$('#clientCannotSign')?.checked||ms.clientCannotSign,reason=($('#field-noSignReason')?.value||ms.noSignReason||'').trim();if(cannot&&db.settings.allowEmployeeOnly){if(!reason)return error('Nurodykite, kodėl klientas negali pasirašyti.')}else if(!ms.signatures.client)return error('Reikalingas kliento parašas arba leidžiamas nepasirašymo paaiškinimas.');if(!ms.stoppedAt||new Date(ms.stoppedAt)<new Date(v.actualStart))return error('Neteisinga vizito pabaiga.');Object.assign(v,{status:'done',actualEnd:ms.stoppedAt,endGPS:ms.endGPS,notes:[...ms.noteValues],comment:ms.comment,signatures:{employee:ms.signatures.employee,client:cannot?'':ms.signatures.client},noSignReason:cannot?reason:'',rateSnapshot:v.rateSnapshot??rateAt(v.serviceId,client(v.clientId).municipalityId,v.date)?.amount??null,supplementSnapshot:v.supplementSnapshot??supplementAt(client(v.clientId),v.serviceId)});if(!persist())return;ms.step='done';render();renderMobileModal();return}
 case'correct-time':correctionForm(id);return;
 case'save-correction':{if(!$('#correction-v2').reportValidity())return;let d=formData('correction-v2'),v=db.visits.find(v=>v.id===ms.id),start=new Date(d.start),end=new Date(d.end);if(!allowedVisit(v)||v.status!=='done')return;if(!(end>start)||end-start>86400000)return error('Pabaiga turi būti vėlesnė; vieno vizito trukmė negali viršyti 24 val.');if(!d.reason.trim())return error('Nurodykite koregavimo priežastį.');if(start.toISOString()===v.actualStart&&end.toISOString()===v.actualEnd)return error('Laikas nepakeistas.');db.corrections.push({id:uid(),visitId:v.id,employeeId:v.employeeId,at:new Date().toISOString(),by:ui.role==='admin'?'Administratorius':'Koordinatorius · '+branchName(branchScope()),reason:d.reason.trim(),before:{start:v.actualStart,end:v.actualEnd},after:{start:start.toISOString(),end:end.toISOString()}});v.actualStart=start.toISOString();v.actualEnd=end.toISOString();doneSave('Faktinis laikas ir koregavimo istorija išsaugoti');return}
 }
 // Preserve the existing calendar, absence and visit flow, with v2 notifications.
 const beforeVisit=a==='save-visit'?db.visits.map(v=>({...v})):null;const beforeIds=a==='save-visit'?new Set(db.visits.map(v=>v.id)):null;const beforeAbs=db.absences.length;const replacementIds=a==='save-replacement'?db.visits.map(v=>({id:v.id,employeeId:v.employeeId})):null;
 await legacy.action(a,b);
 if(a==='save-visit'&&!modalState){let v=ms?.id?db.visits.find(v=>v.id===ms.id):db.visits.find(v=>!beforeIds.has(v.id));if(v){v.rateSnapshot=rateAt(v.serviceId,client(v.clientId).municipalityId,v.date)?.amount??null;v.supplementSnapshot=supplementAt(client(v.clientId),v.serviceId);notifyVisit(v,ms?.id?'Pakeistas vizitas':'Priskirtas naujas vizitas');if(!beforeVisit.some(o=>o.id!==v.id&&o.employeeId===v.employeeId&&o.clientId===v.clientId))notify('Priskirtas naujas klientas',client(v.clientId).name,{clientId:v.clientId,employeeId:v.employeeId,branchId:client(v.clientId).branchId},'naujas klientas');persist();render()}}
 if(a==='save-absence'&&db.absences.length>beforeAbs){let off=db.absences.at(-1);notify('Darbuotojo neatvykimas',emp(off.employeeId).name+' · '+off.type+' · '+off.from+'–'+off.to,{employeeId:off.employeeId,branchId:emp(off.employeeId).branchId},'neatvykimas');persist()}
 if(a==='save-replacement'&&!modalState){for(let old of replacementIds){let v=db.visits.find(v=>v.id===old.id);if(v.employeeId!==old.employeeId){notifyVisit(v,'Priskirtas pavadavimo vizitas');notify('Vizitas perduotas pavaduojančiam darbuotojui',client(v.clientId).name,{visitId:v.id,clientId:v.clientId,employeeId:old.employeeId,branchId:emp(old.employeeId).branchId},'pavadavimas')}}persist();render()}
};
document.addEventListener('submit',ev=>{const map={'client-v2':'v2-save-client','plan-v2':'save-plan','schedule-v2':'save-schedule','suspension-v2':'save-suspension','service-v2':'save-service-v2','rate-v2':'save-rate','task-v2':'save-task','generate-v2':'preview-generation','correction-v2':'save-correction'};if(map[ev.target.id]){ev.preventDefault();action(map[ev.target.id]).catch(err=>{console.error(err);error('Nepavyko išsaugoti. Patikrinkite laukus.')})}});
document.addEventListener('change',async ev=>{let el=ev.target;try{
 if(el.id==='onlyUnread'){ui.onlyUnread=el.checked;render();return}
 if(el.id==='allowEmployeeOnly'&&isAdmin()){db.settings.allowEmployeeOnly=el.checked;persist();toast('Pasirašymo nustatymas išsaugotas');return}
 if(el.id==='clientCannotSign'){modalState.clientCannotSign=el.checked;$('#no-sign-reason').hidden=!el.checked;return}
 if(el.name==='municipalityId'&&el.closest('#client-v2')){for(let row of $$('.assignment-row')){let r=rateAt(row.dataset.service,el.value);$('.rate-label',row).textContent=r?money(r.amount)+'/val.':'Įkainis nenustatytas'}return}
 if(el.id==='document-file'&&isAdmin()&&el.files[0]){let f=el.files[0],ms=modalState;if(f.size>2*1024*1024)return error('Vienas dokumentas gali būti iki 2 MB.');if(!/\.(pdf|docx?|xlsx?|png|jpe?g|txt)$/i.test(f.name))return error('Šis failo tipas nepalaikomas.');let data=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});if(modalState!==ms)return;let owner=documentOwner(ms.kind,ms.id);let record={id:uid(),name:f.name,size:f.size,date:TODAY,data};owner.files.push(record);if(!persist()){owner.files.pop();return}documentForm(ms.kind,ms.id);toast('Dokumentas pridėtas');return}
 }catch(err){console.error(err);error(err.message||'Failo apdoroti nepavyko.');let target=$('#import-result');if(target)target.innerHTML=notice(e(err.message||'Importo klaida.'),'')}
});
document.addEventListener('input',ev=>{if(ev.target.id==='field-noSignReason'&&modalState)modalState.noSignReason=ev.target.value});
render();
